######## BankerNpc
     1	using UnityEngine;
     2	
     3	public class BankerNpc : Npc
     4	{
     5		private bool goldTraded;
     6	
     7		private bool useBonus;
     8	
     9		private int bonusAmount = 19;
    10	
    11		public override void Start()
    12		{
    13			CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.BankerRoom, transform.position, transform);
    14		}
    15	
    16		public override bool HandleConditionalInteraction()
    17		{
    18			switch (DialogManager.dialogDict[myDialogID].CurrentIndex)
    19			{
    20			case 0:
    21				if (goldTraded)
    22				{
    23					DialogManager.dialogDict[myDialogID].CurrentIndex = 3;
    24				}
    25				break;
    26			case 2:
    27				useBonus = player.inventory.ContainsItem("TokenBanker");
    28				if (!goldTraded && player != null && (useBonus || Player.goldWallet.balance > 0))
    29				{
    30					TradeGold(useBonus);
    31				}
    32				break;
    33			case 3:
    34				if (!goldTraded)
    35				{
    36					playerLeavingDialog = true;
    37					return true;
    38				}
    39				break;
    40			case 4:
    41				playerLeavingDialog = true;
    42				return true;
    43			}
    44			return false;
    45		}
    46	
    47		private void TradeGold(bool givenBonus)
    48		{
    49			goldTraded = true;
    50			int num = Mathf.CeilToInt((float)Player.goldWallet.balance * ((!Inventory.EitherPlayerHasItem("TokenBanker")) ? 0.09f : 0.125f));
    51			Player.platWallet.Deposit(Mathf.Clamp(num, 1, Player.platWallet.maxBalance));
    52			GameController.levelPlat += num;
    53			GameController.totalPlat += num;
    54			Player.goldWallet.Withdraw(Player.goldWallet.balance);
    55			SoundManager.PlayAudio("MenuBuy");
    56			PoolManager.GetPoolItem<EmoteEmitter>().Emit(EmoteType.AwwYis, 1, transform.position + Vector3.up * 2.75f);
    57			SoundManager.PlayAudio((!Globals.RandBool) ? "Banker1" : "Banker0");
    58			DialogManager.dialogDict[myDialogID].CurrentIndex = 3;
    59			RunData.miscBankerRoomFound = true;
    60			if (givenBonus)
    61			{
    62				player.inventory.RemoveItem("TokenBanker", forceOverride: false, showNotice: true);
    63				LootManager.DropPlat(transform.position, bonusAmount);
    64			}
    65		}
    66	}
