     1	using UnityEngine;
     2	
     3	public class BossRushNpc : Npc
     4	{
     5		public GameObject bossRushTP;
     6	
     7		public GameObject bossRushTPDisabled;
     8	
     9		private int cost = 10;
    10	
    11		public override void Start()
    12		{
    13			base.Start();
    14			if (GameController.runModifier.HasMod("RushRunMod"))
    15			{
    16				EnableTeleporter();
    17			}
    18		}
    19	
    20		public override bool HandleConditionalInteraction()
    21		{
    22			if (GameController.runModifier.HasMod("RushRunMod") && CurrentDialogIndex < 3)
    23			{
    24				CurrentDialogIndex = 4;
    25				return false;
    26			}
    27			switch (CurrentDialogIndex)
    28			{
    29			case 3:
    30				if (Player.platWallet.balance >= cost)
    31				{
    32					Player.platWallet.Withdraw(cost);
    33					SoundManager.PlayAudio("MenuBuy");
    34					SoundManager.PlayAudio("BossRush0");
    35					GameController.runModifier.AddMod(new RushRunMod());
    36					CurrentDialogIndex = 4;
    37					EnableTeleporter();
    38					PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(7, bossRushTP.transform.position);
    39					PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(4, bossRushTP.transform.position + Vector3.up * 2f);
    40					PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(3, bossRushTP.transform.position + Vector3.left * 1.5f);
    41					PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(3, bossRushTP.transform.position + Vector3.right * 1.5f);
    42				}
    43				break;
    44			case 4:
    45				playerLeavingDialog = true;
    46				return true;
    47			}
    48			return false;
    49		}
    50	
