162		private bool ConditionalRequirementMet(string givenName)
163		{
164			if (GameDataManager.gameData == null || GameDataManager.gameData.gameStats == null)
165			{
166				return true;
167			}
168			switch (givenName)
169			{
170			case "Venture":
171				foreach (string bossName in bossNameList)
172				{
173					if (GameDataManager.gameData.gameStats.GetEnemyDefeatedCount(bossName) > 0)
174					{
175						return true;
176					}
