243		private IEnumerator SpinCard(Transform givenTrans)
244		{
245			Vector2 spinVector = Vector2.zero;
246			int spinCount = 4;
247			float minAngle = -(float)Math.PI / 2f;
248			float maxAngle = (2f * (float)spinCount - 0.5f) * (float)Math.PI;
249			float spinAngle = 0f;
250			int spinStopwatchID = ChaosStopwatch.Begin(4f);
251			bool isSpinning = true;
252			float minRadius = 0f - givenTrans.localPosition.y;
253			float maxRadius = 3f;
254			float radiusValue = 0f;
255			for (int i = 0; i < 5; i++)
256			{
257				skillItems[i].itemSpriteRenderer.sortingLayerName = "Overlay";
258				skillItems[i].itemBGSpriteRenderer.sortingLayerName = "Overlay";
259				skillItems[i].standardSR.sortingLayerName = "Overlay";
260				skillItems[i].empoweredSR.sortingLayerName = "Overlay";
261				skillItems[i].sigSR.sortingLayerName = "Overlay";
262			}
263			while (isSpinning)
264			{
265				float spinValue = Globals.GetSmoothLerpValue(ChaosStopwatch.GetTimePercentage(spinStopwatchID));
266				spinAngle = Mathf.Lerp(minAngle, maxAngle, spinValue);
267				spinVector.x = Mathf.Cos(spinAngle);
268				spinVector.y = Mathf.Sin(spinAngle);
269				radiusValue = Mathf.Lerp(minRadius, maxRadius, Mathf.PingPong(spinValue * 4f, 1f));
270				if (spinValue > 0.25f && spinValue < 0.75f)
271				{
272					radiusValue = Mathf.Clamp(radiusValue, 0.25f, maxRadius);
273				}
274				if (!audioStopwatch.IsRunning)
275				{
276					audioStopwatch.SetDelay(Mathf.Lerp(0.2f, 0.0625f, Mathf.Pow(1f + Mathf.PingPong(spinValue * 2f, 1f), 2f) - 1f), stopCurrent: false, autoStart: true);
277					SoundManager.PlayAudioWithDistance("CardSelect", transform.position);
278				}
279				givenTrans.position = currentPosition + spinVector * (radiusValue + 1f);
280				isSpinning = !ChaosStopwatch.Check(spinStopwatchID);
281				yield return null;
282			}
283			for (int j = 0; j < 5; j++)
284			{
285				skillItems[j].itemSpriteRenderer.sortingLayerName = "Actor";
286				skillItems[j].itemBGSpriteRenderer.sortingLayerName = "Actor";
287				skillItems[j].standardSR.sortingLayerName = "Actor";
288				skillItems[j].empoweredSR.sortingLayerName = "Actor";
289				skillItems[j].sigSR.sortingLayerName = "Actor";
290			}
291		}
