 282			switch (timerType)
 283			{
 284			case TimerType.Local:
 285				if (ChaosStopwatch.Check(instStopwatchID))
 286				{
 287					queueStateChange = true;
 288					switch (currentState)
 289					{
 290					case ActivationState.Deactivated:
 291						currentState = ActivationState.Windup;
 292						break;
 293					case ActivationState.Windup:
 294						currentState = ActivationState.Activated;
 295						break;
 296					case ActivationState.Activated:
 297						currentState = ActivationState.Deactivated;
 298						break;
 299					}
 300				}
 301				break;
 302			case TimerType.Global:
 303				if (!stateCleared)
 304				{
 305					if (globalState != ActivationState.Deactivated)
 306					{
 307						break;
 308					}
 309					stateCleared = true;
 310				}
 311				if (currentState != globalState)
 312				{
 313					currentState = globalState;
 314					queueStateChange = true;
 315				}
 316				break;
 317			case TimerType.GlobalAlt:
 318				tempState = ((!isGlobalAltPrimary) ? globalAltSec : globalAltPri);
 319				if (!stateCleared)
 320				{
 321					if (tempState != ActivationState.Deactivated)
 322					{
